// Данные устройств (UDID, bundle id, Team ID) — ТОЛЬКО в ~/.qa-tester/zichui-app.env (вне проекта), см. README.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Подгрузить локальные параметры устройства/приложения (не коммитятся, не в проекте).
const localEnv = path.join(os.homedir(), '.qa-tester', 'zichui-app.env');
if (fs.existsSync(localEnv)) {
  for (const line of fs.readFileSync(localEnv, 'utf8').split('\n')) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
  }
}
// Тестовые аккаунты (телефон/OTP) — из .qa/accounts.env; читает только этот процесс при прогоне.
const accountsEnv = path.resolve(__dirname, '../accounts.env');
if (fs.existsSync(accountsEnv)) {
  for (const line of fs.readFileSync(accountsEnv, 'utf8').split('\n')) {
    const m = line.match(/^\s*(QA_[A-Z0-9_]+)\s*=\s*(.*)\s*$/);
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
  }
}

const platform = (process.env.PLATFORM || 'android').toLowerCase();
const e = (k: string, d = '') => process.env[k] || d;

const android = {
  platformName: 'Android',
  'appium:automationName': 'UiAutomator2',
  'appium:deviceName': e('ANDROID_DEVICE', 'emulator-5554'),
  'appium:udid': e('ANDROID_DEVICE') || undefined,
  'appium:appPackage': e('APP_ANDROID_PACKAGE'),
  'appium:appActivity': e('APP_ANDROID_ACTIVITY', '.MainActivity'),
  ...(e('APP_ANDROID_APK') ? { 'appium:app': e('APP_ANDROID_APK') } : {}),
  'appium:noReset': true,              // сохраняем вход между тестами
  'appium:autoGrantPermissions': true,
  'appium:newCommandTimeout': 240,
  'appium:locale': 'IL',
  'appium:language': 'he',
};

const ios = {
  platformName: 'iOS',
  'appium:automationName': 'XCUITest',
  'appium:udid': e('IOS_UDID'),
  'appium:bundleId': e('APP_IOS_BUNDLE'),
  ...(e('APP_IOS_APP') ? { 'appium:app': e('APP_IOS_APP') } : {}),
  'appium:noReset': true,
  'appium:usePrebuiltWDA': e('IOS_USE_PREBUILT_WDA', 'true') === 'true',
  'appium:derivedDataPath': e('IOS_WDA_DERIVED', path.join(os.homedir(), '.appium', 'wda-build')),
  'appium:updatedWDABundleId': e('IOS_WDA_BUNDLE') || undefined,
  'appium:xcodeOrgId': e('IOS_TEAM_ID') || undefined,
  'appium:xcodeSigningId': 'Apple Development',
  'appium:wdaLaunchTimeout': 240000,
  'appium:newCommandTimeout': 240,
  'appium:autoAcceptAlerts': false,
};

export const config: WebdriverIO.Config = {
  runner: 'local',
  hostname: e('APPIUM_HOST', '127.0.0.1'),
  port: Number(e('APPIUM_PORT', '4723')),
  path: '/',
  specs: ['./specs/**/*.e2e.ts'],
  maxInstances: 1,                     // один телефон — тесты по одному
  capabilities: [platform === 'ios' ? ios : android] as any,
  logLevel: 'warn',
  waitforTimeout: 15000,
  connectionRetryTimeout: 240000,
  connectionRetryCount: 1,
  framework: 'mocha',
  reporters: ['spec'],
  mochaOpts: { ui: 'bdd', timeout: 300000 },
  before: async () => {
    // iOS: XCUITest помечает элементы React Native visible="false", даже когда они на экране (вкладки, тексты).
    // Поэтому «виден» = элемент существует и его рамка пересекает экран.
    if (driver.isIOS) {
      const win = await driver.getWindowSize();
      browser.overwriteCommand('isDisplayed', async function (this: WebdriverIO.Element) {
        if (!(await this.isExisting())) return false;
        const r = await this.getElementRect(this.elementId).catch(() => null);
        if (!r || r.width <= 0 || r.height <= 0) return false;
        return r.x < win.width && r.x + r.width > 0 && r.y < win.height && r.y + r.height > 0;
      }, true);
    }
    const { ensureAppReady } = await import('./helpers/app.ts');
    await ensureAppReady();
  },
  afterTest: async (test, _ctx, { passed }) => {
    if (!passed) {
      const dir = path.resolve(__dirname, '../screenshots/app-regress');
      fs.mkdirSync(dir, { recursive: true });
      const name = test.title.replace(/[^\p{L}\p{N}]+/gu, '-').slice(0, 80);
      await browser.saveScreenshot(path.join(dir, `${platform}-${name}.png`));
    }
  },
};
